/**
 * The telemetry payload example of docs/privacy-architecture.md §11 (sprint_5 5.9 done-when: generated by a script from
 * the real builder on a seeded ledger, never hand-typed). The block between the doc's markers must be exactly what
 * tests/tools/telemetry-example.ts makes the builder build today, and a payload the schema takes. After changing the
 * builder, the schema or the version, run `pnpm exec tsx tests/tools/telemetry-example.ts` from extension/.
 */
import { readFileSync } from 'node:fs';

import { describe, expect, it } from 'vitest';

import { TelemetryPayload } from '../../../src/telemetry/schema';
import {
  EXAMPLE_DOC,
  EXAMPLE_END,
  EXAMPLE_START,
  telemetryExample,
  withExample,
} from '../../tools/telemetry-example';

describe('docs/privacy-architecture.md: the telemetry payload example', () => {
  it('is exactly the payload the real builder makes of the seeded day', async () => {
    const doc = readFileSync(EXAMPLE_DOC, 'utf8');
    const example = await telemetryExample();
    expect(doc.split(EXAMPLE_START)).toHaveLength(2);
    expect(doc.split(EXAMPLE_END)).toHaveLength(2);
    expect(doc, 'run `pnpm exec tsx tests/tools/telemetry-example.ts` from extension/').toBe(
      withExample(doc, example),
    );
  });

  it('is a payload the schema takes, counting what the seeded day holds', async () => {
    const payload = TelemetryPayload.parse(JSON.parse(await telemetryExample()));
    // Three VERIFIED, one PARTIAL, one NOT_FOUND and one marked NOT_FOUND; the receipt still checking left out.
    expect(payload.counts.muse).toMatchObject({ VERIFIED: 3, PARTIAL: 1, NOT_FOUND: 2 });
    // The receipt graded the day before left out.
    expect(payload.counts.claude).toMatchObject({ VERIFIED: 1, UNVERIFIABLE: 1 });
    expect(payload.coverageHours).toEqual({ gmail: 7, gcal: 9 });
  });
});
